import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel source for the element-wise log subtraction used in KL divergence.
kl_div_cpp_source = (
    "torch::Tensor kl_div_cuda(torch::Tensor pred, torch::Tensor target);"
)

kl_div_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void kl_div_kernel(const float* pred, const float* target, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        // compute log(pred) - log(target)
        out[idx] = logf(pred[idx]) - logf(target[idx]);
    }
}

torch::Tensor kl_div_cuda(torch::Tensor pred, torch::Tensor target) {
    auto size = pred.numel();
    auto out = torch::zeros_like(pred);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    kl_div_kernel<<<num_blocks, block_size>>>(pred.data_ptr<float>(), target.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

# Load the custom CUDA operator for KL divergence.
kl_div_cuda = load_inline(
    name="kl_div",
    cpp_sources=kl_div_cpp_source,
    cuda_sources=kl_div_cuda_source,
    functions=["kl_div_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.kl_div_cuda = kl_div_cuda

    def forward(self, predictions, targets):
        return self.kl_div_cuda(predictions, targets)
